"""Preview and apply compilation-unit moves generated by Eclipse JDT LS."""
from __future__ import annotations

import argparse
from collections.abc import Iterable
from codecs import BOM_UTF8
from collections import deque
from copy import deepcopy
from dataclasses import dataclass
from hashlib import sha256
import json
import os
from pathlib import Path
from queue import Empty, Queue
import re
import shutil
import subprocess
import sys
from tempfile import mkdtemp, NamedTemporaryFile
from threading import Thread
from time import monotonic
from urllib.parse import urlsplit
from urllib.request import url2pathname
import xml.etree.ElementTree as ET
from zipfile import BadZipFile, ZipFile


def require(condition: bool, message: str) -> None:
    if not condition:
        raise ValueError(message)


def git(root: Path, *args: str) -> str:
    completed = subprocess.run(
        ["git", *args], cwd=root, check=True, capture_output=True, encoding="utf-8"
    )
    return completed.stdout.strip()


def clean_worktree(root: Path) -> str:
    require(Path(git(root, "rev-parse", "--show-toplevel")).resolve() == root,
            "The selected directory must be the Git worktree root")
    require(not git(root, "status", "--porcelain=v1", "--untracked-files=normal"),
            "The isolated worktree has uncommitted changes")
    return git(root, "rev-parse", "HEAD")


def worktree_path(root: Path, path: Path) -> Path:
    path = path if path.is_absolute() else root / path
    normalized = Path(os.path.abspath(path))
    resolved = normalized.resolve()
    require(resolved == normalized and resolved.is_relative_to(root),
            f"Path is outside the worktree or uses a symlink: {path}")
    return resolved


def file_uri(uri: str) -> Path:
    parts = urlsplit(uri)
    require(parts.scheme == "file" and not (parts.netloc or parts.query or parts.fragment),
            f"Expected a local file URI: {uri}")
    path = Path(url2pathname(parts.path))
    require(path.is_absolute(), f"Expected an absolute file URI: {uri}")
    return path


def resolve_uri(root: Path, uri: str, links: dict[Path, Path]) -> Path:
    path = file_uri(uri)
    for alias, actual in links.items():
        if path.is_relative_to(alias):
            path = actual / path.relative_to(alias)
            break
    return worktree_path(root, path)


def within_links(root: Path, uri: str, links: dict[Path, Path]) -> Path | None:
    try:
        return resolve_uri(root, uri, links)
    except ValueError:
        return None


def apply_text(original: bytes, edits: list[dict]) -> bytes:
    text = original.decode("utf-8-sig")
    bom = BOM_UTF8 if original.startswith(BOM_UTF8) else b""
    lines = []
    start = 0
    for sep in re.finditer(r"\r\n|\n|\r", text):
        lines.append((start, sep.start()))
        start = sep.end()
    lines.append((start, len(text)))
    crlf = "\r\n" in text and not re.search(r"(?<!\r)\n|\r(?!\n)", text)

    def offset(position: dict) -> int:
        line, column = position["line"], position["character"]
        require(type(line) is int and type(column) is int and 0 <= line < len(lines) and column >= 0,
                f"Invalid LSP position: {position}")
        beginning, end = lines[line]
        units = 0
        for index in range(beginning, end):
            if units == column:
                return index
            units += 2 if ord(text[index]) > 0xFFFF else 1
        require(units == column, f"LSP position falls outside the line or splits a surrogate pair: {position}")
        return end

    converted = []
    for edit in edits:
        require("range" in edit and "newText" in edit, "Unsupported workspace text edit")
        start = offset(edit["range"]["start"])
        end = offset(edit["range"]["end"])
        require(start <= end, "Workspace text edit ends before its start")
        replacement = edit["newText"]
        if crlf:
            replacement = re.sub(r"(?<!\r)\n", "\r\n", replacement)
        converted.append((start, end, replacement))
    converted.sort(key=lambda op: (op[0], op[1]))
    previous_end = 0
    chunks = []
    for start, end, replacement in converted:
        require(start >= previous_end, "Workspace text edits overlap")
        chunks.extend((text[previous_end:start], replacement))
        previous_end = end
    chunks.append(text[previous_end:])
    return bom + "".join(chunks).encode("utf-8")


@dataclass
class Operation:
    kind: str
    path: Path
    payload: bytes | Path


class PreparedEdit:
    def __init__(self, root: Path, workspace_edits: Iterable[dict], links: dict[Path, Path]):
        self.root = root
        self.initial: dict[Path, bytes | None] = {}
        self.final: dict[Path, bytes | None] = {}
        self.operations: list[Operation] = []
        for workspace_edit in workspace_edits:
            self.add_edit(workspace_edit, links)
        require(bool(self.operations), "JDT returned an empty WorkspaceEdit")

    def add_edit(self, workspace_edit: dict, links: dict[Path, Path]) -> None:
        annotations = workspace_edit.get("changeAnnotations", {})
        require(not any(annotation.get("needsConfirmation") for annotation in annotations.values()),
                "JDT requested confirmation for a refactoring change")
        changes = workspace_edit.get("changes") or {}
        ordered = workspace_edit.get("documentChanges") or []
        require(not (changes and ordered), "WorkspaceEdit uses conflicting edit forms")
        if changes:
            ordered = [{"textDocument": {"uri": uri}, "edits": edits} for uri, edits in changes.items()]
        for step in ordered:
            kind = step.get("kind", "text")
            if kind == "rename":
                old = self.path(step["oldUri"], links)
                new = self.path(step["newUri"], links)
                before = self.current(old)
                require(old != new and before is not None and self.current(new) is None,
                        f"Invalid rename or existing destination: {old} -> {new}")
                self.final[old], self.final[new] = None, before
                self.operations.append(Operation("rename", old, new))
            elif kind == "create":
                path = self.path(step["uri"], links)
                require(self.current(path) is None, f"WorkspaceEdit would overwrite {path}")
                self.final[path] = b""
                self.operations.append(Operation("create", path, b""))
            elif kind == "text":
                path = self.path(step["textDocument"]["uri"], links)
                before = self.current(path)
                require(before is not None, f"Cannot edit missing source {path}")
                after = apply_text(before, step["edits"])
                self.final[path] = after
                self.operations.append(Operation("text", path, after))
            else:
                raise ValueError(f"Unsupported WorkspaceEdit resource operation: {kind}")

    def path(self, uri: str, links: dict[Path, Path]) -> Path:
        path = resolve_uri(self.root, uri, links)
        require(path.suffix == ".java" and path.parent.is_dir(),
                f"WorkspaceEdit path must be a Java file in an existing source directory: {path}")
        return path

    def current(self, path: Path) -> bytes | None:
        if path not in self.initial:
            require(not path.exists() or path.is_file(), f"WorkspaceEdit path is not a file: {path}")
            self.initial[path] = path.read_bytes() if path.is_file() else None
            self.final[path] = self.initial[path]
        return self.final[path]

    def hashes(self, contents: dict[Path, bytes | None]) -> dict[str, str | None]:
        return {p.relative_to(self.root).as_posix(): sha256(data).hexdigest() if data is not None else None
                for p, data in contents.items()}

    def renames(self) -> list[tuple[Path, Path]]:
        return [(op.path, op.payload) for op in self.operations if op.kind == "rename"]

    def preview_write(self) -> list[dict]:
        """Apply a group only to the disposable source copy used by a batch preview."""
        changes = []
        for path, final in self.final.items():
            prior = self.initial[path]
            if final == prior:
                continue
            if final is None:
                path.unlink()
                kind = 3
            else:
                atomic_bytes(path, final)
                kind = 1 if prior is None else 2
            changes.append({"uri": path.as_uri(), "type": kind})
        return changes

    def write(self) -> None:
        touched = [path.relative_to(self.root).as_posix() for path in self.initial]
        require(not git(self.root, "status", "--porcelain=v1", "--", *touched),
                "A file from the WorkspaceEdit is no longer clean")
        for path, expected in self.initial.items():
            current = path.read_bytes() if path.is_file() else None
            require(current == expected, f"Source changed after hash validation: {path}")
            if expected is not None:
                git(self.root, "ls-files", "--error-unmatch", "--", path.relative_to(self.root).as_posix())
        indexed = {path for path, original in self.initial.items() if original is not None}
        try:
            for op in self.operations:
                if op.kind == "rename":
                    if op.path in indexed:
                        git(self.root, "mv", "--", op.path.relative_to(self.root).as_posix(),
                            op.payload.relative_to(self.root).as_posix())
                        indexed.remove(op.path)
                        indexed.add(op.payload)
                    else:
                        op.path.rename(op.payload)  # A prior CreateFile is not tracked yet.
                else:
                    atomic_bytes(op.path, op.payload)
            actual = {path: path.read_bytes() if path.is_file() else None for path in self.final}
            require(actual == self.final, "Applied worktree content differs from the JDT preview")
        except (OSError, ValueError, subprocess.CalledProcessError):
            for path, original in self.initial.items():
                if original is None:
                    path.unlink(missing_ok=True)
                else:
                    atomic_bytes(path, original)
            git(self.root, "reset", "--quiet", "HEAD", "--", *touched)
            raise


def atomic_bytes(path: Path, data: bytes) -> None:
    with NamedTemporaryFile(dir=path.parent, prefix=".jdt-edit-", delete=False) as temporary:
        temporary.write(data)
        temp_path = Path(temporary.name)
    try:
        temp_path.replace(path)
    finally:
        temp_path.unlink(missing_ok=True)


def dump_json(path: Path, data: dict) -> None:
    atomic_bytes(path, (json.dumps(data, indent=2, ensure_ascii=False) + "\n").encode("utf-8"))


def external_report(root: Path, name: str) -> Path:
    output = Path(name).resolve()
    require(output.suffix == ".json" and output.parent.is_dir() and not output.is_relative_to(root),
            "Use a JSON report path outside the target worktree with an existing parent")
    return output


def eclipse_project(workspace: Path, root: Path, source_roots: list[str],
                    base_classpath: Path) -> tuple[Path, dict[Path, Path]]:
    project = workspace / "project"
    project.mkdir()
    description = ET.Element("projectDescription")
    ET.SubElement(description, "name").text = "java-refactor"
    ET.SubElement(description, "projects")
    ET.SubElement(description, "buildSpec")
    ET.SubElement(ET.SubElement(description, "natures"), "nature").text = "org.eclipse.jdt.core.javanature"
    resources = ET.SubElement(description, "linkedResources")
    linked_paths = {}
    classpath = ET.Element("classpath")
    seen = set()
    for relative in source_roots:
        actual = worktree_path(root, Path(relative))
        require(actual.is_dir() and actual != root and actual not in seen, f"Invalid source root: {relative}")
        seen.add(actual)
        alias = f"source_{len(seen)}"
        link = ET.SubElement(resources, "link")
        ET.SubElement(link, "name").text = alias
        ET.SubElement(link, "type").text = "2"
        ET.SubElement(link, "locationURI").text = actual.as_uri()
        ET.SubElement(classpath, "classpathentry", kind="src", path=alias, output="bin")
        linked_paths[project / alias] = actual
    classpath.extend(dependency_entries(base_classpath))
    ET.SubElement(classpath, "classpathentry", kind="output", path="bin")
    for name, document in ((".project", description), (".classpath", classpath)):
        ET.indent(document)
        ET.ElementTree(document).write(project / name, encoding="utf-8", xml_declaration=True)
    settings = project / ".settings"
    settings.mkdir()
    (settings / "org.eclipse.jdt.core.prefs").write_text(
        "eclipse.preferences.version=1\norg.eclipse.jdt.core.compiler.codegen.targetPlatform=25\n"
        "org.eclipse.jdt.core.compiler.compliance=25\norg.eclipse.jdt.core.compiler.source=25\n",
        encoding="utf-8",
    )
    return project, linked_paths


def dependency_entries(base_classpath: Path) -> Iterable[ET.Element]:
    """Use the source roots for all SkyWars definitions, including old package locations."""
    for entry in ET.parse(base_classpath).getroot():
        kind, name = entry.get("kind"), entry.get("path", "")
        if kind == "lib":
            path = Path(name)
            require(path.is_absolute() and path.exists(), f"Cached dependency is missing: {name}")
            if path.is_dir():
                print(f"Ignoring compiled class directory: {path.name}", file=sys.stderr)
                continue
            with ZipFile(path) as archive:
                if any(contains_skywars_class(row.filename) for row in archive.infolist()):
                    print(f"Ignoring JAR containing compiled SkyWars classes: {path.name}", file=sys.stderr)
                    continue
        elif kind != "con" or name.split("/", 1)[0] != "org.eclipse.jdt.launching.JRE_CONTAINER":
            continue
        copied = deepcopy(entry)
        for attributes in copied.findall("attributes"):
            for attribute in list(attributes):
                if attribute.get("name") == "gradle.buildServer":
                    attributes.remove(attribute)
        yield copied


def contains_skywars_class(entry: str) -> bool:
    prefix = "META-INF/versions/"
    if entry.startswith(prefix):
        _, _, entry = entry[len(prefix):].partition("/")
    return entry.startswith("me/skywars2/") and entry.endswith(".class")


def source_roots(args, root: Path) -> list[str]:
    defaults = ("src/main/java", "src/checks/java", "media-protocol/src/main/java")
    sources = args.source_root or [name for name in defaults if (root / name).is_dir()]
    return [worktree_path(root, Path(name)).relative_to(root).as_posix() for name in sources]


def copy_sources(root: Path, view: Path, roots: list[str], destinations: Iterable[Path]) -> None:
    """Mirror only tracked Java files so planning a batch never mutates the worktree."""
    for name in git(root, "ls-files", "-z", "--", *roots).split("\0"):
        if name.endswith(".java"):
            original = worktree_path(root, Path(name))
            copy = view / original.relative_to(root)
            copy.parent.mkdir(parents=True, exist_ok=True)
            shutil.copyfile(original, copy)
    directories = [Path(name) for name in roots]
    directories.extend(path.relative_to(root) for path in destinations)
    for directory in directories:
        (view / directory).mkdir(parents=True, exist_ok=True)


class Lsp:
    def __init__(self, command: list[str], state: Path, settings: dict, timeout: float):
        self.stderr = (state / "jdt.stderr.log").open("wb")
        self.incoming = Queue()
        self.settings = settings
        self.timeout = timeout
        self.requests = 0
        self.ready = False
        self.status = deque(maxlen=12)
        self.diagnostics = {}
        flags = subprocess.CREATE_NO_WINDOW | subprocess.BELOW_NORMAL_PRIORITY_CLASS if os.name == "nt" else 0
        self.child = subprocess.Popen(command, cwd=state, stdin=subprocess.PIPE, stdout=subprocess.PIPE,
                                      stderr=self.stderr, creationflags=flags)
        self.reader = Thread(target=self._read, daemon=True)
        self.reader.start()

    def _read(self) -> None:
        stream = self.child.stdout
        try:
            while start := stream.readline():
                key, _, value = start.decode("ascii").strip().partition(":")
                require(key.lower() == "content-length", "Unexpected output on JDT RPC stdout")
                while (header := stream.readline()) not in {b"\r\n", b"\n"}:
                    require(bool(header), "EOF in JDT RPC headers")
                length = int(value.strip())
                require(0 < length <= 64 * 1024 * 1024, "Unexpected JDT RPC message length")
                content = stream.read(length)
                require(len(content) == length, "EOF in JDT RPC message")
                self.incoming.put(json.loads(content))
            self.incoming.put(EOFError("JDT Language Server exited"))
        except (OSError, ValueError) as error:
            self.incoming.put(error)

    def send(self, **message) -> None:
        data = json.dumps({"jsonrpc": "2.0", **message}, ensure_ascii=False).encode("utf-8")
        self.child.stdin.write(f"Content-Length: {len(data)}\r\n\r\n".encode("ascii") + data)
        self.child.stdin.flush()

    def receive(self, deadline: float) -> dict:
        try:
            result = self.incoming.get(timeout=max(0, deadline - monotonic()))
        except Empty as error:
            raise TimeoutError(f"JDT response timed out. Recent statuses: {list(self.status)}") from error
        if isinstance(result, BaseException):
            raise result
        method = result.get("method")
        params = result.get("params") or {}
        if "id" in result and method:
            request_id = result["id"]
            if method == "workspace/configuration":
                configs = []
                for item in params.get("items", []):
                    value = self.settings
                    for segment in item.get("section", "").split(".") if item.get("section") else []:
                        value = value.get(segment, {}) if isinstance(value, dict) else {}
                    configs.append(value)
                self.send(id=request_id, result=configs)
            elif method == "workspace/applyEdit":
                self.send(id=request_id, result={"applied": False, "failureReason": "Preview-only JDT client"})
            elif method == "workspace/workspaceFolders":
                self.send(id=request_id, result=self.folders)
            elif method in {"window/workDoneProgress/create", "client/registerCapability",
                            "client/unregisterCapability", "window/showMessageRequest"}:
                self.send(id=request_id, result=None)
            elif method == "workspace/executeClientCommand":
                self.send(id=request_id, result=[])
            else:
                self.send(id=request_id, error={"code": -32601, "message": f"Unsupported client method: {method}"})
        elif method == "language/status":
            self.status.append((params.get("type"), params.get("message")))
            self.ready |= params.get("type") == "ServiceReady"
        elif method == "textDocument/publishDiagnostics":
            self.diagnostics[params["uri"]] = params["diagnostics"]
        return result

    def request(self, method: str, params: dict | None = None, timeout: float | None = None):
        self.requests += 1
        request_id = self.requests
        self.send(id=request_id, method=method, params=params)
        deadline = monotonic() + (self.timeout if timeout is None else timeout)
        while True:
            response = self.receive(deadline)
            if response.get("id") == request_id and "method" not in response:
                require("error" not in response, f"JDT {method}: {response.get('error')}")
                return response.get("result")

    def initialize(self, project: Path) -> None:
        self.folders = [{"name": "java-refactor", "uri": project.as_uri()}]
        result = self.request("initialize", {
            "processId": os.getpid(), "rootUri": project.as_uri(), "workspaceFolders": self.folders,
            "capabilities": {
                "general": {"positionEncodings": ["utf-16"]},
                "workspace": {"workspaceFolders": True, "configuration": True, "applyEdit": True,
                              "didChangeWatchedFiles": {"dynamicRegistration": True, "relativePatternSupport": True},
                              "workspaceEdit": {"documentChanges": True,
                                                "resourceOperations": ["create", "rename", "delete"]}},
                "textDocument": {"publishDiagnostics": {"versionSupport": True},
                                 "documentSymbol": {"hierarchicalDocumentSymbolSupport": True}},
            },
            "initializationOptions": {
                "workspaceFolders": [project.as_uri()], "bundles": [], "settings": self.settings,
                "extendedClientCapabilities": {"moveRefactoringSupport": True},
            },
        })
        encoding = result["capabilities"].get("positionEncoding", "utf-16")
        require(encoding == "utf-16", f"Unexpected LSP position encoding: {encoding}")
        self.send(method="initialized", params={})
        self.send(method="workspace/didChangeConfiguration", params={"settings": self.settings})
        deadline = monotonic() + self.timeout
        while not self.ready:
            self.receive(deadline)

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, trace):
        try:
            self.request("shutdown", timeout=3)
            self.send(method="exit")
            self.child.wait(timeout=3)
        except (OSError, EOFError, ValueError, subprocess.TimeoutExpired):
            if self.child.poll() is None:
                self.child.terminate()
                try:
                    self.child.wait(timeout=3)
                except subprocess.TimeoutExpired:
                    self.child.kill()
                    self.child.wait(timeout=3)
        finally:
            self.stderr.close()


def server(args, root: Path, preview_destinations: list[Path] | None = None):
    jdt = Path(args.jdt_home).resolve()
    java = Path(args.java_home).resolve()
    java_executable = java / "bin" / ("java.exe" if os.name == "nt" else "java")
    launcher = list((jdt / "plugins").glob("org.eclipse.equinox.launcher_*.jar"))
    require(java_executable.is_file() and len(launcher) == 1, "Invalid Java or JDT installation")
    state_parent = Path(args.state_dir).resolve() if args.state_dir else None
    if state_parent:
        require(not state_parent.is_relative_to(root), "JDT state must be outside the target worktree")
        state_parent.mkdir(parents=True, exist_ok=True)
    state = Path(mkdtemp(prefix="luckywars-jdt-", dir=state_parent)).resolve()
    require(not state.is_relative_to(root), "External JDT state directory required")
    print(f"JDT state: {state}", file=sys.stderr)
    roots = source_roots(args, root)
    require(bool(roots), "No Java source roots found")
    view = root
    if preview_destinations is not None:
        view = state / "source-preview"
        copy_sources(root, view, roots, preview_destinations)
    project, links = eclipse_project(state, view, roots, Path(args.classpath))
    config_folder = {"win32": "config_win", "darwin": "config_mac"}.get(sys.platform, "config_linux")
    configuration = state / "configuration"
    configuration.mkdir()
    shutil.copyfile(jdt / config_folder / "config.ini", configuration / "config.ini")
    command = [
        str(java_executable), "-Xms96m", f"-Xmx{args.heap}", "-XX:+UseSerialGC",
        "-Dfile.encoding=UTF-8", "-Djava.import.generatesMetadataFilesAtProjectRoot=false",
        "-Declipse.application=org.eclipse.jdt.ls.core.id1", "-Declipse.product=org.eclipse.jdt.ls.core.product",
        "-Dosgi.bundles.defaultStartLevel=4", f"-Dosgi.install.area={jdt.as_uri()}/",
        "--add-modules=ALL-SYSTEM", "--add-opens=java.base/java.util=ALL-UNNAMED",
        "--add-opens=java.base/java.lang=ALL-UNNAMED", "--add-opens=java.base/sun.nio.fs=ALL-UNNAMED",
        "-jar", str(launcher[0]), "-configuration", str(configuration), "-data", str(state / "workspace"),
    ]
    settings = {"java": {
        "autobuild": {"enabled": False},
        "import": {"gradle": {"enabled": False}, "maven": {"enabled": False}},
        "configuration": {"updateBuildConfiguration": "disabled",
                          "runtimes": [{"name": "JavaSE-25", "path": str(java), "default": True}]},
        "server": {"launchMode": "Standard"},
    }}
    return Lsp(command, state, settings, args.timeout), project, links, view


@dataclass(frozen=True)
class MoveGroup:
    sources: list[Path]
    destination: Path


def requested_groups(args, root: Path) -> list[MoveGroup]:
    if args.batch:
        require(not args.to, "Provide destinations in --batch without --to")
        batch = json.loads(Path(args.batch).read_text(encoding="utf-8"))
        require(isinstance(batch, list) and bool(batch), "Batch must be a nonempty list of move groups")
    else:
        require(bool(args.to), "A single move needs --to")
        batch = [{"sources": args.move, "to": args.to}]
    seen = set()
    destinations = set()
    groups = []
    roots = [root / name for name in source_roots(args, root)]
    for group in batch:
        files = [worktree_path(root, Path(name)) for name in group["sources"]]
        require(bool(files) and len({p.parent for p in files}) == 1,
                "Use Java sources from one package for each semantic move")
        destination = worktree_path(root, Path(group["to"]))
        require(destination.is_dir() and destination != files[0].parent
                and any(destination.is_relative_to(source) for source in roots),
                f"Prepare an existing destination package under a source root: {destination}")
        for file in files:
            target = destination / file.name
            require(file not in seen and target not in destinations and not target.exists(),
                    f"Duplicate batch source or destination: {file} -> {target}")
            require(file.suffix == ".java" and file.is_file()
                    and any(file.is_relative_to(source) for source in roots), f"Invalid Java source: {file}")
            git(root, "ls-files", "--error-unmatch", "--", file.relative_to(root).as_posix())
            seen.add(file)
            destinations.add(target)
        groups.append(MoveGroup(files, destination))
    return groups


def request_move(client: Lsp, root: Path, links: dict[Path, Path], group: MoveGroup) -> dict:
    options = {"moveKind": "moveResource", "sourceUris": [file.as_uri() for file in group.sources], "params": None}
    destinations = client.request("java/getMoveDestinations", options)
    require(isinstance(destinations, dict) and not destinations.get("errorMessage"),
            f"JDT could not resolve move destinations: {destinations}")
    candidates = [entry for entry in destinations.get("destinations", []) if entry.get("uri")
                  and within_links(root, entry["uri"], links) == group.destination]
    require(len(candidates) == 1, f"Expected one JDT package for {group.destination}, found {len(candidates)}")
    response = client.request("java/move", {**options, "destination": candidates[0], "updateReferences": True})
    require(isinstance(response, dict) and not (response.get("errorMessage") or response.get("confirmationToken")),
            f"JDT declined the move: {response}")
    edit = response.get("edit")
    require(isinstance(edit, dict), "JDT did not return a WorkspaceEdit")
    return edit


def plan(args, root: Path) -> None:
    head = clean_worktree(root)
    output = external_report(root, args.out)
    groups = requested_groups(args, root)
    destinations = [group.destination for group in groups] if args.batch else None
    client, project, links, view = server(args, root, destinations)
    workspace_edits = []
    with client:
        client.initialize(project)
        for index, group in enumerate(groups):
            shadow_group = MoveGroup([view / path.relative_to(root) for path in group.sources],
                                     view / group.destination.relative_to(root))
            edit = request_move(client, view, links, shadow_group)
            prepared = PreparedEdit(view, [edit], links)
            expected = {(file, shadow_group.destination / file.name) for file in shadow_group.sources}
            require(set(prepared.renames()) == expected, "JDT returned file renames different from the requested move")
            workspace_edits.append(edit)
            if index + 1 < len(groups):
                changes = prepared.preview_write()
                client.send(method="workspace/didChangeWatchedFiles", params={"changes": changes})
                for _, path in prepared.renames():
                    uri = path.as_uri()
                    client.send(method="textDocument/didOpen", params={"textDocument": {
                        "uri": uri, "languageId": "java", "version": 1,
                        "text": path.read_bytes().decode("utf-8-sig"),
                    }})
                    symbols = client.request("textDocument/documentSymbol", {"textDocument": {"uri": uri}})
                    client.send(method="textDocument/didClose", params={"textDocument": {"uri": uri}})
                    require(any(symbol.get("name") == path.stem for symbol in symbols or []),
                            f"JDT has not indexed the moved declaration: {path} ({symbols})")
    require(clean_worktree(root) == head, "Worktree changed while JDT was planning the move")
    source_links = {alias: root / path.relative_to(view) for alias, path in links.items()}
    if view != root:
        source_links[view] = root
    prepared = PreparedEdit(root, workspace_edits, source_links)
    dump_json(output, {
        "format": 2, "engine": "Eclipse JDT LS java/move", "worktree": str(root), "head": head,
        "workspaceEdits": workspace_edits, "links": {str(alias): str(path) for alias, path in source_links.items()},
        "originalSha256": prepared.hashes(prepared.initial), "proposedSha256": prepared.hashes(prepared.final),
    })
    print(f"JDT preview only. {len(prepared.renames())} moves, {len(prepared.final)} paths. {args.out}")


def read_plan(path: str, root: Path) -> dict:
    data = json.loads(Path(path).read_text(encoding="utf-8"))
    require(data.get("format") in {1, 2} and Path(data["worktree"]).resolve() == root, "Plan belongs to another worktree")
    return data


def apply_plan(args, root: Path) -> None:
    data = read_plan(args.plan, root)
    require(clean_worktree(root) == data["head"], "Plan belongs to a different Git revision")
    links = {Path(alias): worktree_path(root, Path(actual)) for alias, actual in data["links"].items()}
    edits = data["workspaceEdits"] if data["format"] == 2 else [data["workspaceEdit"]]
    prepared = PreparedEdit(root, edits, links)
    require(data["originalSha256"] == prepared.hashes(prepared.initial), "Original source hashes changed")
    require(data["proposedSha256"] == prepared.hashes(prepared.final), "Proposed workspace hashes changed")
    if args.write:
        prepared.write()
    print(f"{'Applied' if args.write else 'Validated preview'}: {len(prepared.renames())} moves, "
          f"{len(prepared.final)} paths")


def diagnose(args, root: Path) -> None:
    data = read_plan(args.plan, root)
    output = external_report(root, args.out)
    wanted = set()
    for relative, digest in data["proposedSha256"].items():
        file = worktree_path(root, Path(relative))
        require((sha256(file.read_bytes()).hexdigest() if file.is_file() else None) == digest,
                f"Working source differs from the applied plan: {file}")
        if digest is not None:
            wanted.add(file)
    client, project, links, _ = server(args, root)
    diagnostics = {}
    with client:
        client.initialize(project)
        for file in sorted(wanted):
            client.send(method="textDocument/didOpen", params={"textDocument": {
                "uri": file.as_uri(), "languageId": "java", "version": 1,
                "text": file.read_bytes().decode("utf-8-sig"),
            }})
        deadline = monotonic() + args.timeout
        while wanted - diagnostics.keys():
            message = client.receive(deadline)
            if message.get("method") == "textDocument/publishDiagnostics":
                params = message["params"]
                if params.get("version") not in {None, 1}:
                    continue
                file = within_links(root, params["uri"], links)
                if file in wanted:
                    diagnostics[file] = params["diagnostics"]
    errors = {file.relative_to(root).as_posix(): records for file, records in diagnostics.items()
              if any(record.get("severity", 1) == 1 for record in records)}
    dump_json(output, {"files": {file.relative_to(root).as_posix(): records
                                for file, records in diagnostics.items()}, "errorFiles": sorted(errors)})
    require(not errors, f"JDT found reconciliation errors in {len(errors)} files. See {args.out}")
    print(f"JDT reported no changed-file errors across {len(diagnostics)} files. See {args.out}")


def jdt_options(parser: argparse.ArgumentParser) -> None:
    for option, env in (("jdt-home", "JDTLS_HOME"), ("java-home", "JDTLS_JAVA_HOME"),
                        ("classpath", "JDTLS_CLASSPATH")):
        default = os.environ.get(env)
        parser.add_argument(f"--{option}", default=default, required=not default)
    parser.add_argument("--source-root", action="append", help="Java source directory relative to worktree")
    parser.add_argument("--state-dir", help="External parent directory for disposable JDT state and logs")
    parser.add_argument("--timeout", type=float, default=150, help="Seconds per JDT request")
    parser.add_argument("--heap", default="768m")
    parser.add_argument("--out", required=True, help="Output JSON path with an existing parent directory")


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--worktree", required=True, help="Dedicated clean Git worktree root")
    subparsers = parser.add_subparsers(dest="action", required=True)
    preview = subparsers.add_parser("plan")
    jdt_options(preview)
    input_scope = preview.add_mutually_exclusive_group(required=True)
    input_scope.add_argument("--move", action="append", help="Relative Java source path")
    input_scope.add_argument("--batch", help="JSON file with ordered {sources, to} move groups")
    preview.add_argument("--to", help="Existing destination package directory relative to worktree")
    apply = subparsers.add_parser("apply")
    apply.add_argument("--plan", required=True)
    apply.add_argument("--write", action="store_true", help="Apply validated JDT edits using git mv")
    diagnostics = subparsers.add_parser("diagnose")
    jdt_options(diagnostics)
    diagnostics.add_argument("--plan", required=True)
    args = parser.parse_args()
    root = Path(args.worktree).resolve()
    try:
        {"plan": plan, "apply": apply_plan, "diagnose": diagnose}[args.action](args, root)
    except (OSError, EOFError, ValueError, KeyError, subprocess.CalledProcessError, BadZipFile) as error:
        parser.exit(1, f"Java refactor: {error}\n")


if __name__ == "__main__":
    main()
